require('dotenv').config();

module.exports = function(RED) {
  const SessionManager = require('kumva-insights/utils/session-manager');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');
  const WebhookManager = require('kumva-insights/utils/webhook-manager');

  let globalSessionManager = null;
  const registeredPaths = new Map();

  if (!RED._kumvaWebhookManagers) {
    RED._kumvaWebhookManagers = new Map();
  }
  const webhookManagers = RED._kumvaWebhookManagers;

  function logNodeEvent(node, stage, payload) {
    const label = node.name || node.type || 'kumva-start-campaign';
    console.log(`[KUMVA][${label}] ${stage}`, JSON.stringify(payload));
  }

  function createScopedSessionKey(campaignId, identity, channel) {
    const safeCampaignId = String(campaignId || '').trim();
    const safeIdentity = String(identity || '').trim();
    if (safeCampaignId && safeIdentity) {
      return `${channel}:${safeCampaignId}:${safeIdentity}`;
    }
    if (safeCampaignId) {
      return `${channel}:${safeCampaignId}`;
    }
    if (safeIdentity) {
      return `${channel}:${safeIdentity}`;
    }
    return null;
  }

  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();
    }
    return { sessionManager: globalSessionManager };
  }

  function registerWebhookEndpoint(webhookPath, webhookManager, flowId, node, campaignId) {
    if (!webhookPath) {
      throw new Error('A webhook path is required in the start campaign configuration');
    }

    // todo: handle webhook registration differently. fist verify if it exists and associated with an active flow. if not continue execution else warn of collision
    const existingRegistration = registeredPaths.get(webhookPath);
    if (existingRegistration) {
      if (existingRegistration.nodeId !== node.id || existingRegistration.campaignId !== campaignId) {
        throw new Error(`Webhook path "${webhookPath}" is already registered. Choose a unique webhook path.`);
      }
    } else {
      registeredPaths.set(webhookPath, { flowId, campaignId, nodeId: node.id });
    }

    if (!RED.httpNode._kumvaWebhooks) RED.httpNode._kumvaWebhooks = new Map();
    if (RED.httpNode._kumvaWebhooks.has(webhookPath)) {
      return;
    }

    RED.httpNode._kumvaWebhooks.set(webhookPath, true);

    RED.httpNode.post(webhookPath, async (req, res) => {
      try {
        const payload = req.body || {};
        const activeCampaignId = node._currentCampaignId || campaignId || node.id;
        const managerKey = flowId || webhookPath;
        const webhookMgr = webhookManagers.get(webhookPath) || webhookManagers.get(`${managerKey}:${webhookPath}`) || webhookManagers.get(managerKey) || webhookManager;
        logNodeEvent(node, 'webhook-received', {
          webhookPath,
          campaignId: activeCampaignId,
          method: req.method,
          body: payload
        });

        if (!webhookMgr) {
          return res.status(400).json({ success: false, error: 'No manager' });
        }

        const response = webhookMgr.parseAfricasTalkingPayload(payload);
        if (!response) {
          logNodeEvent(node, 'webhook-parse-failed', { webhookPath, campaignId: activeCampaignId, body: payload });
          return res.status(400).json({ success: false, error: 'Unable to parse payload' });
        }

        const channel = response.type === 'dtmf' ? 'voice' : 'sms';
        const sessionKey = createScopedSessionKey(activeCampaignId, response.sessionIdentity || response.phoneNumber || response.sessionId, channel);
        const { sessionManager } = await initializeGlobals();

        logNodeEvent(node, 'webhook-parsed', {
          webhookPath,
          campaignId: activeCampaignId,
          sessionKey,
          response
        });

        if (!sessionKey) {
          return res.status(400).json({ success: false, error: 'No stable session identity available' });
        }

        const existingSession = await sessionManager.getSession(sessionKey);
        if (!existingSession.exists) {
          await sessionManager.createSession(sessionKey, {
            sessionKey,
            campaignId: activeCampaignId,
            phoneNumber: response.phoneNumber,
            campaignType: channel,
            status: 'active',
            source: 'webhook',
            sessionIdentity: response.sessionIdentity || response.phoneNumber || response.sessionId,
            createdAt: new Date().toISOString(),
            lastUpdated: new Date().toISOString()
          }, 3600);
        }

        const waitingNode = webhookMgr.getWaitingNode(sessionKey);
        if (waitingNode?.callback) {
          logNodeEvent(node, 'dispatching-to-wait-node', { webhookPath, campaignId: activeCampaignId, sessionKey });
          setImmediate(() => {
            waitingNode.callback(response);
            webhookMgr.unregisterWaitingNode(sessionKey);
          });
        } else {
          const queued = webhookMgr.queuePendingResponse(sessionKey, response);
          logNodeEvent(node, queued ? 'queued-for-wait-node' : 'no-wait-node-ready', {
            webhookPath,
            campaignId: activeCampaignId,
            sessionKey,
            queued
          });
        }

        res.json({ success: true, sessionKey, campaignId: activeCampaignId, webhookPath, queued: !!webhookMgr.pendingResponses.get(sessionKey) });
      } catch (error) {
        console.error('[KUMVA][StartCampaign] webhook-error', error);
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  function KumvaStartCampaignNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = this.z || this.id;

    const initiationMode = config.initiationMode || 'outbound';
    const campaignType = config.campaignType || 'sms';
    const webhookPath = config.webhookPath || '/kumva/webhook';
    const baseUrl = process.env.KUMVA_WEBHOOK_BASE_URL;
    const webhookManager = new WebhookManager();
    const webhookUrl = `${String(baseUrl).replace(/\/$/, '')}${webhookPath}`;

    webhookManagers.set(flowId, webhookManager);
    webhookManagers.set(webhookPath, webhookManager);
    webhookManagers.set(`${flowId}:${webhookPath}`, webhookManager);
    node._registeredWebhookPaths = new Set();

    initializeGlobals().catch(e => node.error(e.message));

    try {
      registerWebhookEndpoint(webhookPath, webhookManager, flowId, node, node.id);
      node._registeredWebhookPaths.add(webhookPath);
      node.status({ fill: 'blue', shape: 'dot', text: `Listening: ${webhookPath}` });
    } catch (error) {
      node.error(error.message);
      node.status({ fill: 'red', shape: 'ring', text: 'Webhook error' });
    }

    node.on('input', async function(msg) {
      try {
        const phoneNumber = msg.phoneNumber || msg.contactData?.phone || msg.contactData?.[config.phoneColumn || 'phone'];
        const campaignId = msg.campaignId || `campaign_${Date.now()}`;

        if (!phoneNumber || !campaignId) {
          return node.error('Missing phoneNumber or campaignId');
        }

        node._currentCampaignId = campaignId;

        const effectiveCredentials = {
          username: node.credentials?.username || process.env.KUMVA_AT_USERNAME || process.env.AT_USERNAME || config.username || '',
          apiKey: node.credentials?.apiKey || process.env.KUMVA_AT_API_KEY || process.env.AT_API_KEY || config.apiKey || ''
        };

        const campaignData = {
          campaignId,
          phoneNumber,
          campaignType,
          initiationMode,
          contactData: msg.contactData || {},
          initialMessage: msg.initialMessage || '', // set it to be {type: enum(tts, audio, sms), content: string}
          webhookUrl,
          webhookPath,
          credentials: effectiveCredentials,
          shortCode: config.shortCode || null,
          callerId: config.callerId || null,
          sessionTimeout: helpers.timeToSeconds(config.sessionTimeout || '3600s')
        };

        const outputMsg = {
          ...msg,
          campaignId,
          phoneNumber,
          campaignData,
          initiationMode,
          credentials: campaignData.credentials,
          webhookUrl,
          webhookPath,
          _kumva: {
            campaignId,
            webhookUrl,
            webhookPath,
            mode: initiationMode
          }
        };

        logNodeEvent(node, 'context-ready', {
          campaignId,
          phoneNumber,
          webhookPath,
          initiationMode,
          campaignType,
          msg: outputMsg
        });
        node.status({ fill: 'green', shape: 'dot', text: `Campaign ready: ${campaignId}` });
        node.send(outputMsg);
      } catch (error) {
        console.error('[KUMVA][StartCampaign] error', error);
        node.error(`StartCampaign: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.on('close', (done) => {
      webhookManagers.delete(flowId);
      node._registeredWebhookPaths.forEach((webhookPath) => {
        registeredPaths.delete(webhookPath);
      });
      done();
    });
  }

  RED.httpAdmin.get('/kumva/webhook/validate/:path', (req, res) => {
    const rawPath = req.params.path || '';
    const path = rawPath.startsWith('/') ? rawPath : '/' + rawPath;
    const excludeNodeId = req.query.excludeNodeId || req.query.nodeId;
    const registration = registeredPaths.get(path);
    const available = !registration || (excludeNodeId && registration.nodeId === excludeNodeId);
    res.json({ available, path, registeredBy: registration?.nodeId || null });
  });

  RED.nodes.registerType('kumva-start-campaign', KumvaStartCampaignNode, {
    credentials: {
      username: { type: 'text' },
      apiKey: { type: 'password' }
    }
  });
};